export function startPhotoStudy(book,owner,photo,photoView){const v=state(book,owner),source=photoStudySource(photo,photoView);if(!source||!newPhotoStudyWork(source))return false;const id=`draft-${++v.serial}`;v.drafts.set(id,Object.assign(makeSlot(source),{name:`Draft ${v.serial}`}));v.active=id;v.screen='draft';return true;}
function lines(strokes){return strokes.map(s=>{const p=decodeStudyPoints(s.points);return p.length===1?`<circle cx="${p[0].x}" cy="${p[0].y}" r="2.5"/>`:`<polyline points="${s.points}" fill="none" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`;}).join('');}
function paper(s,w,editable=false,a=null){return `<svg class="study-paper" ${editable?'data-study-paper tabindex="0" role="application" aria-label="Drawing paper. Use arrows to move; Enter to draw or place a label."':'role="img" aria-label="Kept drawing. Numbered pointers match the labels below."'} viewBox="0 0 ${s.paper.width} ${s.paper.height}"><rect width="${s.paper.width}" height="${s.paper.height}" fill="#fffdf4"/><g fill="#183f39" stroke="#183f39"><g data-study-lines>${lines(w.strokes)}</g><g data-study-preview></g></g>${w.labels.map((l,i)=>l.at?`<g class="study-marker" transform="translate(${l.at.x} ${l.at.y})"><circle r="${s.paper.width*.045}"/><text style="font-size:${s.paper.width*.055}px" text-anchor="middle" dominant-baseline="central">${i+1}</text></g>`:'').join('')}${editable?`<g data-study-cursor transform="translate(${a.cursor.x} ${a.cursor.y})" pointer-events="none"><circle r="12"/><path d="M-22 0H22M0-22V22"/></g>`:''}</svg>`;}
