function shelf(v){const view=photoStudiesView(v.book),items=view.items,total=items.length;if(v.page===null){const last=[...items].reverse().find(x=>x.readable);v.page=Math.floor((last?.index??Math.max(0,total-1))/8);}v.page=Math.max(0,Math.min(v.page,Math.max(0,Math.ceil(total/8)-1)));const start=v.page*8,drafts=[...v.drafts.entries()];v.draftPage=Math.max(0,Math.min(v.draftPage,Math.max(0,Math.ceil(drafts.length/8)-1)));return `<h2 id="study-title" tabindex="-1">Photo studies</h2><p>Open a photograph in Lens Bench, choose a patch, then make a study.</p>${view.status==='unavailable'?'<p>This saved format is unavailable here. Your original remains in your Notes download. Drafts remain open.</p>':''}${drafts.length?`<section><h3>Continue a visit draft</h3><ol start="${v.draftPage*8+1}">${drafts.slice(v.draftPage*8,v.draftPage*8+8).map(([id,a])=>`<li>${button(`data-study-draft="${esc(id)}"`,a.name)}</li>`).join('')}</ol><div class="study-actions">${button(`data-study-draft-page="-1"${v.draftPage===0?' disabled':''}`,'Previous drafts')}${button(`data-study-draft-page="1"${(v.draftPage+1)*8>=drafts.length?' disabled':''}`,'Next drafts')}</div></section>`:''}<h3>Kept records</h3>${total?`<p>Studies ${start+1}–${Math.min(start+8,total)} of ${total}</p><ol start="${start+1}">${items.slice(start,start+8).map(x=>`<li>${x.readable?button(`data-study-card="${esc(x.id)}"`,`Study ${x.index+1} · ${x.raw.source.title}`):'<p>Study unavailable here. Its original stays unchanged in your Notes download.</p>'}</li>`).join('')}</ol><div class="study-actions">${button(`data-study-page="-1"${start===0?' disabled':''}`,'Previous studies')}${button(`data-study-page="1"${start+8>=total?' disabled':''}`,'Next studies')}</div>`:'<p>No study has been kept yet.</p>'}`;}
export function photoStudiesPage(book,owner){const v=state(book,owner);let body;if(v.screen==='card'){const x=photoStudiesView(book).items.find(x=>x.id===v.card&&x.readable);if(x){const old=v.readonly.get(x.id);if(!old||old.raw!==x.raw||old.rawSource!==x.raw.source||old.rawWork!==x.raw.work)v.readonly.set(x.id,Object.assign(makeSlot(x.raw.source,x.raw.work),{raw:x.raw,rawSource:x.raw.source,rawWork:x.raw.work}));body=`<p>Study ${x.index+1}</p>${activePage(slot(v),true,v.copies.has(x.id))}`;}else body='<h2 id="study-title" tabindex="-1">This study is unavailable here</h2><p>Your original remains in your Notes download.</p>';}else if(v.screen==='draft'&&slot(v))body=activePage(slot(v));else body=shelf(v);return `<div class="study-page lens-page" data-lens-root data-photo-study-root><header><div class="study-actions">${button('data-study-back','Back to Lens Bench')}${button('data-study-shelf','Photo studies shelf')}${button('data-study-hear data-speak=""','Hear this page')}</div><h1>Photo studies</h1></header>${body}<p class="study-visit-note">Leaving or reloading loses studies that have not been kept.</p></div>`;}
